import{_ as r,a as i,b as l,c as s,d as t,e as n,f as d,g as p,h as a,i as o,j as c,k as u,l as m}from"./chunks/ADB8.B4evyQaN.js";import{_ as b,o as h,c as g,a3 as v}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Android Debug Bridge (ADB)","description":"","frontmatter":{"source_hash":"3c220d5612","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/ADB.md","filePath":"fr/troubleshoot/ADB.md"}'),_={name:"fr/troubleshoot/ADB.md"};function f(z,e,A,D,w,B){return h(),g("div",null,[...e[0]||(e[0]=[v('<h3 id="prepare-your-device-for-debug" tabindex="-1">Préparer votre appareil pour le débogage <a class="header-anchor" href="#prepare-your-device-for-debug" aria-label="Permalink to &quot;Préparer votre appareil pour le débogage {#prepare-your-device-for-debug}&quot;">​</a></h3><p>Cette étape est obligatoire pour s&#39;y connecter via ADB par une connexion physique. Si votre appareil n&#39;a pas de connecteur USB physique, vous devez utiliser ADB via Wi-Fi (documentation à venir).</p><p>Si vous voulez déboguer un smartphone, passez directement <a href="#smartphone">ici</a>.</p><h4 id="smartwatch" tabindex="-1">Montre connectée <a class="header-anchor" href="#smartwatch" aria-label="Permalink to &quot;Montre connectée {#smartwatch}&quot;">​</a></h4><ol><li>Activez les Options pour les développeurs<br> Paramètres -&gt; À propos -&gt; Versions -&gt; Numéro de build<br> Appuyez 7 fois sur le numéro de build jusqu&#39;à ce que la montre affiche « vous êtes développeur ».<br><img src="'+r+'" style="zoom:75%;"></li><li>Paramètres -&gt; Options pour les développeurs -&gt; Débogage ADB<br> Activez le débogage ADB<br><img src="'+i+'" style="zoom:75%;"></li></ol><h4 id="smartphone" tabindex="-1">Smartphone <a class="header-anchor" href="#smartphone" aria-label="Permalink to &quot;Smartphone {#smartphone}&quot;">​</a></h4><ol><li>Activez les Options pour les développeurs<br> Paramètres -&gt; À propos du téléphone -&gt; Informations sur le logiciel -&gt; Numéro de build<br> Appuyez 7 fois sur le numéro de build jusqu&#39;à ce que le téléphone affiche « vous êtes développeur ».<br><img src="'+l+'" style="zoom:75%;"></li><li>Paramètres -&gt; Options pour les développeurs -&gt; Débogage USB<br> Activez le débogage ADB<br><img src="'+s+'" style="zoom:75%;"></li></ol><h3 id="install-adb-on-a-windows-computer" tabindex="-1">Installer ADB sur un ordinateur Windows <a class="header-anchor" href="#install-adb-on-a-windows-computer" aria-label="Permalink to &quot;Installer ADB sur un ordinateur Windows {#install-adb-on-a-windows-computer}&quot;">​</a></h3><ol><li><p>Téléchargez <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> sur votre ordinateur.<br><code>1</code> Ouvrez le dossier Téléchargements<br><code>2</code> Ouvrez le fichier téléchargé<br><code>3</code> Sélectionnez tous les fichiers<br><code>4</code> Copiez-les dans le <code>5</code> dossier adb que vous avez créé dans C:</p><img src="'+t+'"></li><li><p>Ouvrez une nouvelle fenêtre d&#39;invite de commandes (<code>Démarrer -&gt; Exécuter - &gt; cmd</code>) avec les droits d&#39;administrateur.<br><img src="'+n+'"></p></li></ol><h3 id="sideload-an-app-with-adb-in-windows" tabindex="-1">Installer une application avec ADB sous Windows <a class="header-anchor" href="#sideload-an-app-with-adb-in-windows" aria-label="Permalink to &quot;Installer une application avec ADB sous Windows {#sideload-an-app-with-adb-in-windows}&quot;">​</a></h3><ol><li>Branchez votre appareil (montre/téléphone) à votre ordinateur avec un câble USB et déverrouillez l&#39;écran.</li><li>Saisissez <code>cd \\adb</code><br><img src="'+d+'"></li><li>Saisissez <code>adb devices</code><br><img src="'+p+'"></li><li>Regardez l&#39;appareil connecté et autorisez le débogage, en choisissant toujours.<br><img src="'+a+'" style="zoom:75%;"><br><img src="'+o+'" style="zoom:75%;"></li><li>Saisissez à nouveau <code>adb devices</code><br> Votre appareil doit maintenant apparaître dans la liste.<br><img src="'+c+'"></li><li>Copiez le fichier à installer dans le dossier C:\\ADB (appelons-le <code>myapplication.apk</code> pour l&#39;exemple ; si son nom contient des espaces, renommez-le en quelque chose de court et simple, comme <code>oop.apk</code> ou <code>xdrip.apk</code>).</li><li>Saisissez la commande <code>adb install -r myapplication.apk</code> et attendez la fin de l&#39;opération (remplacez <code>myapplication</code> par le nom de votre application).</li><li>L&#39;application doit maintenant être présente sur votre appareil.</li></ol><h3 id="install-adb-on-a-mac" tabindex="-1">Installer ADB sur un Mac <a class="header-anchor" href="#install-adb-on-a-mac" aria-label="Permalink to &quot;Installer ADB sur un Mac {#install-adb-on-a-mac}&quot;">​</a></h3><ol><li>Téléchargez <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> sur votre ordinateur.<br><code>1</code> Ouvrez le dossier Téléchargements dans le Finder<br><code>2</code> Faites un clic droit sur le dossier platform-tools<br><code>3</code> Sélectionnez Nouveau terminal au dossier</li></ol><img src="'+u+'"><h3 id="sideload-an-app-with-adb-in-ios" tabindex="-1">Installer une application avec ADB sous macOS <a class="header-anchor" href="#sideload-an-app-with-adb-in-ios" aria-label="Permalink to &quot;Installer une application avec ADB sous macOS {#sideload-an-app-with-adb-in-ios}&quot;">​</a></h3><ol><li><p>Branchez votre appareil (montre/téléphone) à votre ordinateur avec un câble USB et déverrouillez l&#39;écran.</p></li><li><p>Saisissez <code>./adb devices</code><br><img src="'+m+'"></p></li><li><p>Regardez l&#39;appareil connecté et autorisez le débogage, en choisissant toujours.<br><img src="'+a+'" style="zoom:75%;"><br><img src="'+o+'" style="zoom:75%;"></p></li><li><p>Saisissez à nouveau <code>./adb devices</code><br> Votre appareil doit maintenant apparaître dans la liste.</p></li><li><p>Copiez le fichier à installer dans le dossier platform-tools (appelons-le <code>myapplication.apk</code> pour l&#39;exemple ; si son nom contient des espaces, renommez-le en quelque chose de court et simple, comme <code>oop.apk</code> ou <code>xdrip.apk</code>).</p></li><li><p>Saisissez la commande <code>./adb install -r myapplication.apk</code> et attendez la fin de l&#39;opération (remplacez <code>myapplication</code> par le nom de votre application).</p></li><li><p>L&#39;application doit maintenant être présente sur votre appareil.</p></li></ol><h3 id="install_failed_version_downgrade" tabindex="-1">INSTALL_FAILED_VERSION_DOWNGRADE <a class="header-anchor" href="#install_failed_version_downgrade" aria-label="Permalink to &quot;INSTALL_FAILED_VERSION_DOWNGRADE {#install_failed_version_downgrade}&quot;">​</a></h3><p>Cela signifie probablement que l&#39;application est déjà présente sur votre appareil dans une version plus récente.</p><p>Essayez de la trouver et de la désinstaller.</p><p>S&#39;il est impossible de la désinstaller, essayez de l&#39;installer avec l&#39;option de rétrogradation :</p><p>(Windows) <code>adb install -r -d myapplication.apk</code></p><p>(Mac) <code>./adb install -r -d myapplication.apk</code></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.08.02" target="_blank" rel="noreferrer"><em>Dernière modification le 4/8/2024</em></a></p>',24)])])}const k=b(_,[["render",f]]);export{y as __pageData,k as default};
